    sharedLixId,
    readOnly = false,
    onEditorialContext$,
    onManuscriptFocus$,
  }: TwyneEditorProps) => {
    const clientSig = useConvexClient();
    const auth = useAuth();
    const store = useStore<EditorStore>({
      editor: null,
