      mermaidSource: "",
      noteInputKind: null,
      noteText: "",
      notes: [],
      hasSelection: false,
      selectionAction: null,
      notePopover: null,
      suggestionPopover: null,
      stampVisible: false,
      lastSavedAt: null,
      userCommentPopover: null,
      canUndo: false,
      canRedo: false,
      activeFolioId: activeFolioId ?? "",
      layout: activeFolio?.layout ?? DEFAULT_LAYOUT,
      headerText: activeFolio?.header ?? "",
      footerText: activeFolio?.footer ?? "",
      showLayout: false,
      layoutPanelMaxH: 544,
      exportingPdf: false,
      includePersonaCommentsInExport: false,
      showFindReplace: false,
