        verticalAlignment: null,
        borderColor: null,
        borderStyle: null,
        borderWidth: null,
        stylePreset: null,
      },
      slashOpen: false,
      slashQuery: "",
      slashLeft: 0,
      slashTop: 0,
      zenMode: false,
      openPicker: null,
      currentColor: null,
      currentHighlight: null,
      currentFontFamily: null,
      currentFontSize: null,
