--- src/components/editor/math/math-source-editor.ts	
+++ src/components/editor/math/math-source-editor.ts	
@@ -1,214 +1,221 @@
 import type { Editor } from "@tiptap/core";
 import { renderLatex, type MathDisplayMode } from "./math-renderer";

 export type MathNodeName = "inlineMath" | "blockMath";

 export interface MathSourceEditorOptions {
   editor: Editor;
   getPos: () => number | undefined;
   nodeName: MathNodeName;
   source: string;
   label: string;
   onClose: () => void;
 }

 export interface MathSourceEditor {
   dom: HTMLFormElement;
   input: HTMLTextAreaElement;
   focus: () => void;
   destroy: () => void;
 }

 function updateSource(
   editor: Editor,
   getPos: () => number | undefined,
   nodeName: MathNodeName,
   source: string,
 ): boolean {
   const pos = getPos();
   if (typeof pos !== "number") return false;

   return editor
     .chain()
     .command(({ tr }) => {
       const node = tr.doc.nodeAt(pos);
       if (!node || node.type.name !== nodeName) return false;

       tr.setNodeMarkup(pos, undefined, {
         ...node.attrs,
         source,
       });
       return true;
     })
     .focus()
     .run();
 }

 /**
  * A small DOM editor used inside both math NodeViews. It intentionally commits
  * through the Tiptap transaction pipeline, so edits are undoable and survive
  * the manuscript's ordinary HTML persistence path.
  */
 export function createMathSourceEditor(
   options: MathSourceEditorOptions,
 ): MathSourceEditor {
   const form = document.createElement("form");
   form.className = "twyne-math-source-editor";
   form.setAttribute("data-math-source-editor", options.nodeName);

   const label = document.createElement("label");
   label.className = "twyne-math-source-label";
   label.textContent = options.label;

   const input = document.createElement("textarea");
   input.className = "twyne-math-source-input";
   input.rows = options.nodeName === "blockMath" ? 3 : 2;
   input.value = options.source;
   input.spellcheck = false;
   input.autocapitalize = "off";
   input.autocomplete = "off";
   input.setAttribute("aria-label", options.label);

   const actions = document.createElement("span");
   actions.className = "twyne-math-source-actions";

   const preview = document.createElement("div");
   preview.className = "twyne-math-source-preview";
   preview.setAttribute("aria-live", "polite");
   preview.setAttribute(
     "aria-label",
     `${options.nodeName === "blockMath" ? "Block" : "Inline"} equation preview`,
   );

   const display: MathDisplayMode =
     options.nodeName === "blockMath" ? "block" : "inline";

   const save = document.createElement("button");
   save.className = "twyne-math-source-save";
   save.type = "submit";
   save.textContent = "Render equation";

   const cancel = document.createElement("button");
   cancel.className = "twyne-math-source-cancel";
   cancel.type = "button";
   cancel.textContent = "Cancel";

   actions.append(save, cancel);
   label.append(input);
   form.append(label, preview, actions);

   // Live preview: same renderer the NodeView uses once the edit is saved,
   // debounced so typing doesn't re-render KaTeX per keystroke. The preview
   // never writes back to the document — saving still goes through the
   // Tiptap transaction pipeline in `submit`.
   let previewGeneration = 0;
   let previewTimer: ReturnType<typeof setTimeout> | null = null;

   const showPreviewPlaceholder = (message: string) => {
     preview.className = "twyne-math-source-preview";
     preview.replaceChildren();
     const hint = document.createElement("span");
     hint.className = "twyne-math-source-preview-hint";
     hint.textContent = message;
     preview.append(hint);
   };

   const renderPreview = async () => {
     const generation = ++previewGeneration;
     const source = input.value;
     if (!source.trim()) {
       showPreviewPlaceholder("A live preview of the equation appears here.");
       return;
     }
     const result = await renderLatex(source, display);
     if (generation !== previewGeneration) return;
     preview.replaceChildren();
     if (result.error) {
       preview.className =
         "twyne-math-source-preview twyne-math-source-preview-error";
       const prefix = document.createElement("strong");
       prefix.textContent = "Invalid LaTeX";
       const detail = document.createElement("span");
       detail.className = "twyne-math-source-preview-message";
       detail.textContent = result.error;
       preview.append(prefix, detail);
       return;
     }
     preview.className = "twyne-math-source-preview";
     const output = document.createElement("span");
     output.className = "twyne-math-source-preview-output";
     output.innerHTML = result.html;
     preview.append(output);
   };

   const schedulePreview = () => {
     if (previewTimer) clearTimeout(previewTimer);
     previewTimer = setTimeout(() => {
       previewTimer = null;
       void renderPreview();
     }, 300);
   };

   const closeAndFocusNode = () => {
     const pos = options.getPos();
     options.onClose();
     if (typeof pos === "number") {
       options.editor.chain().setNodeSelection(pos).focus().run();
     } else {
       options.editor.commands.focus();
     }
   };

   const submit = (event: SubmitEvent) => {
     event.preventDefault();
     if (
       updateSource(
         options.editor,
         options.getPos,
         options.nodeName,
         input.value,
       )
     ) {
       options.onClose();
     }
   };

   const keydown = (event: KeyboardEvent) => {
     if (event.key === "Escape") {
       event.preventDefault();
       event.stopPropagation();
       closeAndFocusNode();
       return;
     }

     if (
       event.key === "Enter" &&
       !event.shiftKey &&
       (event.metaKey || event.ctrlKey || options.nodeName === "inlineMath")
     ) {
       event.preventDefault();
       event.stopPropagation();
       form.requestSubmit();
     }
   };

   const cancelEdit = () => closeAndFocusNode();

+  const onPreviewInput = () => schedulePreview();
+
   form.addEventListener("submit", submit);
   input.addEventListener("keydown", keydown);
+  input.addEventListener("input", onPreviewInput);
   cancel.addEventListener("click", cancelEdit);
+  void renderPreview();

   return {
     dom: form,
     input,
     focus: () => {
       input.focus();
       input.setSelectionRange(input.value.length, input.value.length);
     },
     destroy: () => {
+      previewGeneration++;
+      if (previewTimer) clearTimeout(previewTimer);
       form.removeEventListener("submit", submit);
       input.removeEventListener("keydown", keydown);
+      input.removeEventListener("input", onPreviewInput);
       cancel.removeEventListener("click", cancelEdit);
     },
   };
 }

