         store.userCommentPopover = {
           mode: "compose",
           visible: true,
           id: "draft-margin",
           author: "You",
           text: "",
           quote,
           createdAt: Date.now(),
           x: geom.x,
           top: geom.top,
           bottom: geom.bottom,
           maxH: geom.maxH,
           from: range.from,
           to: range.to,
           resolved: false,
           replies: [],
           draft: restoreDraft,
         };
