                   </span>
                   <input
                     id="writer-handle"
                     type="text"
                     value={store.handleDraft}
                     onInput$={(e) => {
                       store.handleDraft = (e.target as HTMLInputElement).value;
                       store.handleError = null;
                       store.handleToast = null;
