                srcset="/assets/landing/product-finished-v2-sm.webp 512w, /assets/landing/product-finished-v2-lg.webp 1024w"
                sizes="(min-width: 768px) 64rem, 100vw"
                width={1024}
                height={1024}
                alt=""
