import { chromium } from "@playwright/test";

const shots = [
  ["landing-platepreviews--brief", "plate-brief"],
  ["landing-platepreviews--draft", "plate-draft"],
  ["landing-platepreviews--notes", "plate-notes"],
  ["landing-platepreviews--sources", "plate-sources"],
  ["editor-insertpanels--diagram-modal", "insert-diagram"],
  ["ui-textmodal--diagram-with-live-preview", "modal-preview"],
];

const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on("pageerror", (e) => errors.push(`PAGEERROR: ${e.message}`));
for (const [id, name] of shots) {
  await page.goto(
    `http://localhost:6006/iframe.html?id=${id}&viewMode=story`,
    { waitUntil: "networkidle", timeout: 60000 },
  );
  await page.waitForTimeout(2500);
  await page.screenshot({ path: `/tmp/opencode/${name}.png` });
  console.log("shot", name);
}
console.log("errors:", errors.length ? errors.slice(0, 10) : "none");
await browser.close();

