   if (!isBrowser()) return;
   try {
     const rec: BriefRecord = { folioId, brief, updatedAt: Date.now() };
     await reqAsPromise(
       (await openDb())
         .transaction("brief", "readwrite")
         .objectStore("brief")
         .put(rec),
