cat > ./repro-editor.tmp.mjs <<'EOF'
import { chromium } from "@playwright/test";
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on("pageerror", (e) => errors.push(`PAGEERROR: ${e.message.slice(0, 200)}`));
await page.goto("http://127.0.0.1:5173/editor/", { waitUntil: "domcontentloaded", timeout: 60000 });
await page.waitForTimeout(3000);
// Seed a folio via raw IndexedDB (db "twyne", v4)
await page.evaluate(() => new Promise((resolve, reject) => {
  const open = indexedDB.open("twyne", 4);
  open.onsuccess = () => {
    const db = open.result;
    const now = Date.now();
    const tx = db.transaction(["folios", "folio-content", "meta"], "readwrite");
    tx.objectStore("folios").put({ id: "repro-folio", name: "Repro", type: "draft", createdAt: now, updatedAt: now });
    tx.objectStore("folio-content").put({ folioId: "repro-folio", html: "<p>Start here. </p>", updatedAt: now });
    tx.objectStore("meta").put({ key: "active-folio-id", value: "repro-folio", updatedAt: now });
    tx.oncomplete = () => resolve("seeded");
    tx.onerror = () => reject(tx.error);
  };
  open.onerror = () => reject(open.error);
}).then((r) => console.log("SEED:", r)).catch((e) => console.log("SEED-FAIL:", String(e).slice(0, 200))));
await page.reload({ waitUntil: "domcontentloaded" });
try {
  await page.waitForSelector("#twyne-editor-mount .ProseMirror", { timeout: 45000 });
  console.log("EDITOR: mounted");
} catch { console.log("EDITOR: NOT mounted"); }
await page.screenshot({ path: "/tmp/opencode/editor-look.png" });
await browser.close();
console.log("errors:", errors.length ? errors.slice(0, 6) : "none");
EOF
