 export interface StoredUsageCursor {
   occurredAt: number;
   eventKey: string;
 }

 export interface StoredUsagePageInput {
   from: number | null;
   to: number;
   after?: StoredUsageCursor;
   limit: number;
 }

 function timestampRange(from: number | null, to: number): IDBKeyRange {
   return from === null
     ? IDBKeyRange.upperBound(to, true)
     : IDBKeyRange.bound(from, to, false, true);
 }

 /** Insert once by eventKey. Existing attempts are successful no-ops. */
 export async function addUsageEventRecordToIdb(
   record: StoredUsageEventRecord,
 ): Promise<boolean> {
   if (!isBrowser()) return false;
   try {
     return await tx(IDB_USAGE_EVENT_STORE, "readwrite", async (t) => {
       const store = t.objectStore(IDB_USAGE_EVENT_STORE);
       const existing = await reqAsPromise<StoredUsageEventRecord | undefined>(
         store.get(record.eventKey),
       );
       if (existing) return false;
       await reqAsPromise(store.add(record));
       return true;
     });
   } catch {
     return false;
   }
 }

 /** Bounded chronological page; equal timestamps are ordered by eventKey. */
 export async function listUsageEventRecordsFromIdb(
   input: StoredUsagePageInput,
 ): Promise<StoredUsageEventRecord[]> {
   if (!isBrowser()) return [];
   const limit = Math.max(1, Math.min(200, Math.floor(input.limit)));
   try {
     return await tx(
       IDB_USAGE_EVENT_STORE,
       "readonly",
       (t) =>
         new Promise<StoredUsageEventRecord[]>((resolve, reject) => {
           const rows: StoredUsageEventRecord[] = [];
           const request = t
             .objectStore(IDB_USAGE_EVENT_STORE)
             .index(IDB_USAGE_OCCURRED_AT_INDEX)
             .openCursor(timestampRange(input.from, input.to));
           request.onerror = () => reject(request.error);
           request.onsuccess = () => {
             const cursor = request.result;
             if (!cursor || rows.length >= limit) {
               resolve(rows);
               return;
             }
             const row = cursor.value as StoredUsageEventRecord;
             const after = input.after;
             const isAfter =
               !after ||
               row.occurredAt > after.occurredAt ||
               (row.occurredAt === after.occurredAt &&
                 row.eventKey.localeCompare(after.eventKey) > 0);
             if (isAfter) rows.push(row);
             cursor.continue();
           };
         }),
     );
   } catch {
     return [];
   }
 }

 export async function markUsageEventsSynchronizedToIdb(
   eventKeys: readonly string[],
   accountId: string,
 ): Promise<void> {
   if (!isBrowser() || eventKeys.length === 0) return;
   try {
     await tx(IDB_USAGE_EVENT_STORE, "readwrite", async (t) => {
       const store = t.objectStore(IDB_USAGE_EVENT_STORE);
       for (const eventKey of eventKeys) {
         const row = await reqAsPromise<StoredUsageEventRecord | undefined>(
           store.get(eventKey),
         );
         if (!row || row.synchronizedAccountId) continue;
         await reqAsPromise(
           store.put({
             ...row,
             synchronizedAccountId: accountId,
             excludedFromSync: undefined,
           }),
         );
       }
     });
   } catch {
     /* sync acknowledgement can retry safely */
   }
 }

 /** Freeze currently-unassigned rows on this device before switching account. */
 export async function excludeUnsynchronizedUsageEventsFromIdb(): Promise<void> {
   if (!isBrowser()) return;
   try {
     await tx(
       IDB_USAGE_EVENT_STORE,
       "readwrite",
       (t) =>
         new Promise<void>((resolve, reject) => {
           const store = t.objectStore(IDB_USAGE_EVENT_STORE);
           const request = store.openCursor();
           request.onerror = () => reject(request.error);
           request.onsuccess = () => {
             const cursor = request.result;
             if (!cursor) {
               resolve();
               return;
             }
             const row = cursor.value as StoredUsageEventRecord;
             if (!row.synchronizedAccountId && !row.excludedFromSync) {
               cursor.update({ ...row, excludedFromSync: true });
             }
             cursor.continue();
           };
         }),
     );
   } catch {
     /* preserve rows; unresolved switches remain safe by default */
   }
 }

 export async function loadWritingActivityDetailFromIdb(
   activityKey: string,
 ): Promise<WritingActivityDetail | null> {
   if (!isBrowser()) return null;
   try {
     return (
       (await reqAsPromise<WritingActivityDetail | undefined>(
         (await openDb())
           .transaction(IDB_WRITING_ACTIVITY_STORE)
           .objectStore(IDB_WRITING_ACTIVITY_STORE)
           .get(activityKey),
       )) ?? null
     );
   } catch {
     return null;
   }
 }

 export async function putWritingActivityDetailToIdb(
   detail: WritingActivityDetail,
 ): Promise<void> {
   if (!isBrowser()) return;
   try {
     await reqAsPromise(
       (await openDb())
         .transaction(IDB_WRITING_ACTIVITY_STORE, "readwrite")
         .objectStore(IDB_WRITING_ACTIVITY_STORE)
         .put(detail),
     );
   } catch {
     /* writing remains available if activity telemetry storage fails */
   }
 }

 export async function listWritingActivityDetailsFromIdb(input: {
   fromDay: string;
   toDay: string;
   limit: number;
 }): Promise<WritingActivityDetail[]> {
   if (!isBrowser()) return [];
   const limit = Math.max(1, Math.min(2_000, Math.floor(input.limit)));
   try {
     return await tx(
       IDB_WRITING_ACTIVITY_STORE,
       "readonly",
       (t) =>
         new Promise<WritingActivityDetail[]>((resolve, reject) => {
           const rows: WritingActivityDetail[] = [];
           const request = t
             .objectStore(IDB_WRITING_ACTIVITY_STORE)
             .index(IDB_WRITING_DAY_INDEX)
             .openCursor(
               IDBKeyRange.bound(input.fromDay, input.toDay, false, true),
             );
           request.onerror = () => reject(request.error);
           request.onsuccess = () => {
             const cursor = request.result;
             if (!cursor || rows.length >= limit) {
               resolve(rows);
               return;
             }
             rows.push(cursor.value as WritingActivityDetail);
             cursor.continue();
           };
         }),
     );
   } catch {
     return [];
   }
 }

 export async function deleteLocalUsageHistoryFromIdb(
   input: {
     includeWritingActivity?: boolean;
   } = {},
 ): Promise<void> {
   if (!isBrowser()) return;
   const stores = [
     IDB_USAGE_EVENT_STORE,
     ...(input.includeWritingActivity ? [IDB_WRITING_ACTIVITY_STORE] : []),
   ];
   try {
     await tx(stores, "readwrite", (t) => {
       for (const store of stores) t.objectStore(store).clear();
     });
   } catch {
     /* explicit UI surfaces report their own retry state */
   }
 }

 /* ── AI settings (single record, key="current") ──────────────── */

 export async function loadAiSettingsFromIdb(): Promise<AiSettings | null> {
   if (!getLocalStorage() && !hasIndexedDb()) return null;
   const local = readLocalStorageJson<AiSettings>(AI_SETTINGS_STORAGE_KEY);
   if (local) return local;
   if (hasIndexedDb()) {
     try {
       const db = await openDb();
       const rec =
         (await reqAsPromise<MetaRecord | undefined>(
           db
             .transaction("ai-settings")
             .objectStore("ai-settings")
             .get("current"),
         )) ?? null;
       const value = (rec?.value as AiSettings | undefined) ?? null;
       if (value) return value;
     } catch {
       // Fall through to localStorage.
     }
   }
   return null;
 }

 /**
  * Announce that the AI settings changed.
  *
  * The orchestrator memoises the settings for the life of the page, so a key
  * added on the Settings route was invisible to every feature until a reload —
  * which is how a writer with a perfectly good OpenAI key ended up on the
  * hosted path being told they were not signed in. An event rather than a
  * direct call because `ai-orchestrator` already imports this module.
  */
 function announceAiSettingsSaved(): void {
   if (typeof window === "undefined") return;
   if (typeof window.dispatchEvent !== "function") return;
   window.dispatchEvent(new CustomEvent("twyne:ai-settings-saved"));
 }

 export async function saveAiSettingsToIdb(settings: AiSettings): Promise<void> {
   if (!getLocalStorage() && !hasIndexedDb()) return;
   writeLocalStorageJson(AI_SETTINGS_STORAGE_KEY, settings);
   announceAiSettingsSaved();
   if (!hasIndexedDb()) return;
   try {
     const rec: MetaRecord = {
       key: "current",
       value: settings,
       updatedAt: Date.now(),
     };
     await reqAsPromise(
       (await openDb())
         .transaction("ai-settings", "readwrite")
         .objectStore("ai-settings")
         .put(rec),
     );
   } catch {
     /* ignore */
   }
 }

 /* ── Lix blob (the versioned draft store) ───────────────────────── */

 /* ── Downloaded on-device model files ───────────────────────────── */

 export interface ModelFileRecord {
   id: string;
   blob: Blob;
   bytes: number;
   updatedAt: number;
 }

 /** Save a downloaded model file under its remote URL as the key. */
 export async function saveModelFileToIdb(
   id: string,
   blob: Blob,
 ): Promise<void> {
   if (!isBrowser()) return;
   try {
     const rec: ModelFileRecord = {
       id,
       blob,
       bytes: blob.size,
       updatedAt: Date.now(),
     };
     await reqAsPromise(
       (await openDb())
         .transaction("models", "readwrite")
         .objectStore("models")
         .put(rec),
     );
   } catch {
     // A cache write failure must not fail a download the caller awaited.
   }
 }

 export async function loadModelFileFromIdb(id: string): Promise<Blob | null> {
   if (!isBrowser()) return null;
   try {
     const db = await openDb();
     const rec = await reqAsPromise<ModelFileRecord | undefined>(
       db.transaction("models").objectStore("models").get(id),
     );
     return rec?.blob instanceof Blob ? rec.blob : null;
   } catch {
     return null;
   }
 }

 export async function listModelFilesFromIdb(
   prefix: string,
 ): Promise<ModelFileRecord[]> {
   if (!isBrowser()) return [];
   try {
     const db = await openDb();
     const all = await reqAsPromise<ModelFileRecord[]>(
       db.transaction("models").objectStore("models").getAll(),
     );
     return all.filter((rec) => rec.id.startsWith(prefix));
   } catch {
     return [];
   }
 }

 export async function deleteModelFileFromIdb(id: string): Promise<void> {
   if (!isBrowser()) return;
   try {
     await reqAsPromise(
       (await openDb())
         .transaction("models", "readwrite")
         .objectStore("models")
         .delete(id),
     );
   } catch {
     /* ignore */
   }
 }

 /* ── Voice notes (recorded audio, kept beside its transcript) ───── */

 interface VoiceNoteRecord {
   id: string;
   blob: Blob;
   updatedAt: number;
 }

 export async function saveVoiceNoteBlob(id: string, blob: Blob): Promise<void> {
   if (!isBrowser()) return;
   const rec: VoiceNoteRecord = { id, blob, updatedAt: Date.now() };
   await tx("voice-notes", "readwrite", (t) => {
     t.objectStore("voice-notes").put(rec);
   });
 }

 export async function loadVoiceNoteBlob(id: string): Promise<Blob | null> {
   if (!isBrowser()) return null;
   try {
     const db = await openDb();
     const rec = await reqAsPromise<VoiceNoteRecord | undefined>(
       db.transaction("voice-notes").objectStore("voice-notes").get(id),
     );
     return rec?.blob instanceof Blob ? rec.blob : null;
   } catch {
     return null;
   }
 }

 export async function deleteVoiceNoteBlob(id: string): Promise<void> {
   if (!isBrowser()) return;
   try {
     await tx("voice-notes", "readwrite", (t) => {
       t.objectStore("voice-notes").delete(id);
     });
   } catch {
     // The transcript is the record of consequence; a stranded blob is not
     // worth failing a delete over.
   }
 }

 export async function loadLixBlobFromIdb(): Promise<Blob | null> {
   if (!isBrowser()) return null;
   try {
     const db = await openDb();
     const rec =
       (await reqAsPromise<MetaRecord | undefined>(
         db.transaction("lix-blob").objectStore("lix-blob").get("current"),
       )) ?? null;
     const v = rec?.value;
     if (v instanceof Blob) return v;
     if (v instanceof ArrayBuffer) return new Blob([v]);
     if (v instanceof Uint8Array) return new Blob([v]);
     return null;
   } catch {
     return null;
   }
 }

 export async function saveLixBlobToIdb(blob: Blob): Promise<void> {
   if (!isBrowser()) return;
   try {
     const rec: MetaRecord = {
       key: "current",
       value: blob,
       updatedAt: Date.now(),
     };
     await reqAsPromise(
       (await openDb())
         .transaction("lix-blob", "readwrite")
         .objectStore("lix-blob")
         .put(rec),
     );
   } catch {
     /* ignore */
   }
 }

 /* ── Comments (inline user comments) ─────────────────────────────── */

 export async function loadCommentsFromIdb(): Promise<unknown[]> {
   if (!isBrowser()) return [];
   try {
     const db = await openDb();
     return reqAsPromise<unknown[]>(
       db.transaction("comments").objectStore("comments").getAll(),
     );
   } catch {
     return [];
   }
 }

 export async function saveCommentsToIdb(comments: unknown[]): Promise<void> {
   if (!isBrowser()) return;
   try {
     await tx("comments", "readwrite", async (t) => {
       const store = t.objectStore("comments");
       store.clear();
       for (const c of comments) store.put(c);
     });
   } catch {
     /* ignore */
   }
 }

 /* ── Wipe (debug + privacy) ─────────────────────────────────────── */

 export async function clearIdbStore(): Promise<void> {
   if (!isBrowser()) return;
   try {
     const db = await openDb();
     const stores = Array.from(db.objectStoreNames);
     await tx(stores, "readwrite", async (t) => {
       for (const name of stores) t.objectStore(name).clear();
     });
   } catch {
     /* ignore */
   }
 }

